### Discussed in https://github.com/sqlalchemy/sqlalchemy/discussions/11308


```py
from sqlalchemy import create_engine
from sqlalchemy import ForeignKey, select
from sqlalchemy.ext.asyncio import AsyncAttrs, async_sessionmaker, create_async_engine
from sqlalchemy.orm import (
    Session,
    DeclarativeBase,
    Mapped,
    MappedAsDataclass,
    mapped_column,
    selectin_polymorphic,
    with_polymorphic,
)

engine = create_engine("sqlite://", echo="debug")


class Base(DeclarativeBase, MappedAsDataclass, kw_only=True):
    pass

class Employee(Base):
    __tablename__ = "employee"
    id: Mapped[int] = mapped_column(primary_key=True, init=False)
    name: Mapped[str]
    type: Mapped[str] = mapped_column(init=False)

    __mapper_args__ = {
        "polymorphic_identity": "employee",
        "polymorphic_on": "type",
        "polymorphic_abstract": True,
    }

    def __repr__(self):
        return f"{self.__class__.__name__}({self.name!r})"


class Engineer(Employee):
    __tablename__ = "engineer"
    id: Mapped[int] = mapped_column(
        ForeignKey("employee.id"), primary_key=True, init=False
    )
    engineer_name: Mapped[str] = mapped_column(repr=False)

    __mapper_args__ = {
        "polymorphic_identity": "engineer",
    }


class Manager(Employee):
    __tablename__ = "manager"
    id: Mapped[int] = mapped_column(
        ForeignKey("employee.id"), primary_key=True, init=False
    )
    manager_name: Mapped[str]

    __mapper_args__ = {
        "polymorphic_identity": "manager",
    }


class CEO(Manager):
    __tablename__ = "ceo"
    id: Mapped[int] = mapped_column(
        ForeignKey("manager.id"), primary_key=True, init=False
    )

    department: Mapped[str]
    __mapper_args__ = {
        "polymorphic_identity": "ceo",
    }


Base.metadata.create_all(engine)

with Session(engine) as ses:
    ses.add(CEO(department="ololo", manager_name="ceo", name="ceoname"))
    ses.commit()

with Session(engine) as ses:
    stmt = select(Employee).where(Employee.name == 'ceoname').options(
        selectin_polymorphic(Employee, classes=[Manager, CEO]),
    )

    data = ses.scalars(stmt)

    for x in data:
        assert "manager_name" in data.__dict__
